+        // iVec (2, 0, 1)
+        // jVec (1, 2, 0)
+        // kVec (0, 1, 2)
+        final int i = this.i * 2 + this.j * 1 + this.k * 0;
+        final int j = this.i * 0 + this.j * 2 + this.k * 1;
+        final int k = this.i * 1 + this.j * 0 + this.k * 2;
