+                new CoordIJK(1, 5, 0),  // 1
+                new CoordIJK(0, 5, 4),  // 2
+                new CoordIJK(0, 1, 5),  // 3
+                new CoordIJK(4, 0, 5),  // 4
+                new CoordIJK(5, 0, 1)   // 5
