+                new CoordIJK(1, 2, 0),  // 1
+                new CoordIJK(0, 2, 1),  // 2
+                new CoordIJK(0, 1, 2),  // 3
+                new CoordIJK(1, 0, 2),  // 4
+                new CoordIJK(2, 0, 1)   // 5
+            };
+        }
