+            }
+        } else {
+            for (int i = 0; i < newRotations; i++)
+                current = H3Index.h3Rotate60ccw(current);
+        }
+
+        rotations[0] = (rotations[0] + newRotations) % 6;
+        out[0] = current;
+
+        return E_SUCCESS;
+    }
+
+}
