+    private static int count(Map<Map<String, String>, Map<Long, Map<String, Double>>> data) {
+        int size = 0;
+        for (Map.Entry<Map<String, String>, Map<Long, Map<String, Double>>> entry : data.entrySet()) {
+            size += entry.getValue().entrySet().size();
+        }
+        return size;
+    }
