+            super(data);
+            this.type = type;
+            this.context = context;
+        }
+
+        @Override
+        public String getWriteableName() {
+            return type;
+        }
+
+        @Override
+        public Version getMinimalSupportedVersion() {
+            return Version.CURRENT;
+        }
+
+        @Override
+        public EnumSet<Metadata.XContentContext> context() {
+            return context;
+        }
+    }
