+        { 0, 0, 1 },  // direction 1
+        { 0, 1, 0 },  // direction 2
+        { 0, 1, 1 },  // direction 3
+        { 1, 0, 0 },  // direction 4
+        { 1, 0, 1 },  // direction 5
+        { 1, 1, 0 }   // direction 6
